  tielion: {
    id: "tielion",
    name: "沧州铁狮子",
    alias: "镇海吼",
    primary: "bronze",
    secondary: "religion",
    era: "后周广顺三年(953年)",
    relicName: "沧州铁狮子",
    intro: "现存最大的古代铸铁艺术品之一,张口怒吼千年,镇守沧州。",
    comic: [
      "公元953年,后周时期。沧州人把我铸造出来,为了镇住海里的「蛟龙」和水患。",
      "我是用「泥范明浇法」整体一次浇铸而成的,原重约三十二吨。",
      "我背上驮着巨大的莲花盆,昂首张口,像在怒吼,人们叫我「镇海吼」。",
      "一千年风雨,我锈了、裂了,可我依然站在这里。",
    ],
    knowledge: [
      { keys: ["多大", "哪年", "朝代", "什么时候", "历史"], a: "我铸造于后周广顺三年,公元953年,已经有一千多年历史了。" },
      { keys: ["镇海吼", "名字", "为什么叫"], a: "古人以为海啸、洪水是蛟龙作怪,我张口怒吼,能镇住海患,所以叫「镇海吼」。" },
      { keys: ["多重", "重量", "吨"], a: "我原重约三十二吨,是中国现存最大的古代铸铁艺术品之一。" },
      { keys: ["怎么铸", "铸造", "工艺", "泥范"], a: "工匠用「泥范明浇法」把我整体浇铸出来,反映了五代时期高超的冶铁技术。" },
      { keys: ["在哪", "哪里", "沧州"], a: "我就在河北沧州,是这座城市的象征。" },
      { keys: ["出土", "挖掘", "挖出", "发现", "考古", "考古发现", "来历"], a: "我可没被挖出来过。从公元 953 年铸成起,我就一直站在河北沧州的原址上,1961 年还被列为第一批全国重点文物保护单位。" }
    ],
    quiz: [
      { q: "沧州铁狮子通高约多少?", options: ["约 5.5 米", "约 15 米", "约 1.5 米", "约 0.5 米"], answer: 0, tip: "它身长约 6 米、通高约 5.5 米,原重约三十二吨。" },
      { q: "沧州铁狮子铸造于哪个朝代?", options: ["汉代", "唐代", "后周", "明代"], answer: 2, tip: "后周广顺三年(953年)。" },
      { q: "铁狮子又被人们称作什么?", options: ["镇海吼", "石敢当", "金鳌", "铁牛"], answer: 0, tip: "张口怒吼镇海患,故名「镇海吼」。" },
      { q: "铁狮子主要用什么材质铸成?", options: ["青铜", "铸铁", "木材", "石材"], answer: 1, tip: "它是铸铁杰作。" },
      { q: "铁狮子原重约多少?", options: ["3吨", "8吨", "32吨", "100吨"], answer: 2, tip: "原重约32吨。" },
      { q: "古人铸造它的主要用意是?", options: ["装饰花园", "镇水患、祈福", "储水", "当路标"], answer: 1, tip: "镇海吼,意在镇水患。" }
    ],
    history: "沧州铁狮子铸于后周广顺三年(953年),位于河北沧州,别名「镇海吼」。它采用泥范明浇法整体铸造,原重约三十二吨,是中国现存最大的古代铸铁艺术品之一。古人以它镇水患、祈福佑,千余年来一直是沧州的象征。铁狮子身长约 6 米、通高约 5.5 米,以泥范明浇法一次整体浇铸而成,在世界冶铁史上占有重要地位;1961 年被国务院公布为第一批全国重点文物保护单位,至今仍矗立在河北沧州的原址上。"
  },

  baozhen: {
    id: "baozhen",
    name: "错金豹镇",
    alias: "汉代席镇",
    primary: "bronze",
    secondary: "household",
    era: "汉代",
    relicName: "汉代错金豹镇",
    intro: "青铜铸豹,错金为纹,压在席角的小小猛兽。",
    comic: [
      "汉代人跪坐于席上,席子角容易卷起来。于是,我出现了——压席子的「镇」。",
      "我是青铜铸成的豹子,工匠还在我身上嵌进了金丝,这叫「错金」。",
      "我趴在席角,神气又安静,既压得住席子,也压得住人心。",
    ],
    knowledge: [
      { keys: ["镇", "什么是镇", "席镇", "作用"], a: "「镇」是压席子的用具。汉代流行把镇做成动物造型,如豹、虎、羊,既实用又美观。" },
      { keys: ["错金", "工艺", "金丝"], a: "错金是把金丝嵌入青铜器表面凹槽的工艺,极其精细华贵,是汉代的高级装饰手法。" },
      { keys: ["豹", "为什么是豹", "造型"], a: "豹象征威猛有力,用它做镇,既有装饰意味,又能「镇」住席角。" },
      { keys: ["材质", "什么做", "青铜"], a: "我是青铜铸造,表面错金,所以看着金灿灿的。" },
      { keys: ["出土", "挖掘", "挖出", "发现", "考古", "考古发现", "来历"], a: "像我这样的青铜错金豹镇,大多是从汉代的高等级墓葬中出土的,是主人身份和审美的象征。" }
    ],
    quiz: [
      { q: "像错金豹镇这样的青铜镇,大多出土于?", options: ["汉代的高等级墓葬", "商代祭祀坑", "唐代窑址", "元代驿站"], answer: 0, tip: "它们是墓主身份与审美的象征。" },
      { q: "席镇要压住席角,个头通常多大?", options: ["几厘米到十厘米上下", "半米以上", "1 米以上", "5 毫米以内"], answer: 0, tip: "镇做得小巧而压手,正合压在席角。" },
      { q: "「镇」这类器物主要用来做什么?", options: ["照明", "压席角", "盛水", "写字"], answer: 1, tip: "镇是压席子的用具。" },
      { q: "「错金」是一种什么工艺?", options: ["把金丝嵌入青铜凹槽", "把黄金熔化浇铸", "给器物刷金漆", "用金箔包裹"], answer: 0, tip: "错金是嵌金工艺。" },
      { q: "下面哪种动物常被做成汉代的镇?", options: ["熊猫", "豹", "鲸鱼", "孔雀"], answer: 1, tip: "豹、虎、羊等常见。" },
      { q: "错金豹镇的主要材质是?", options: ["青铜", "陶瓷", "木材", "白银"], answer: 0, tip: "青铜为主,表面错金。" },
      { q: "汉代人为什么爱用动物造型的镇?", options: ["没有别的材料", "既有装饰又能镇席", "方便携带", "为了养宠物"], answer: 1, tip: "实用与美观兼具。" }
    ],
    history: "镇是汉代人压席子的用具。错金豹镇以青铜铸成豹形,表面用错金工艺嵌入金丝纹饰,造型写实而华贵,既压席角又显身份,是汉代金属工艺与生活审美结合的代表。汉代人席地而坐,席角容易卷起,于是用「镇」压住四角,并常铸成虎、豹、羊等动物形象;这类错金铜镇多出土于汉代高等级墓葬,工艺考究,也是墓主身份与审美的象征。"
  },

