    history: "唐 · 白玉蹲狮以温润白玉圆雕成狮,蹲坐昂首,鬃毛与肌肉刻画饱满有力。狮子经丝绸之路传入中国后成为瑞兽,象征威严与护佑。此器兼具唐代玉雕的雄浑气度与细腻工艺,是盛唐玉作的代表之一。唐代玉作选料讲究、雕工圆熟,玉狮、玉兽一类题材多出土于墓葬与窖藏,是考察这一时期玉雕工艺的珍贵实物。"
