  lvyoutaozhu: {
    id: "lvyoutaozhu",
    name: "绿釉陶猪",
    alias: "汉代的小猪",
    primary: "ceramic",
    secondary: "mingqi",
    era: "汉代",
    relicName: "汉 · 绿釉陶猪",
    intro: "圆滚滚的陶猪,披着一身绿釉。汉代人「事死如生」,把它请进墓葬,为墓主在另一个世界备好肉食;它是沧州博物馆的特色藏品。",
    comic: [
      "我是一只陶做的猪,圆滚滚的身子,穿着一身绿莹莹的釉衣。别笑我胖——汉代人心里的猪,越壮越有福气。",
      "汉代人讲究「事死如生」:生前吃的肉、养的牲畜,也要带到另一个世界去。于是像我这样的陶猪,就被请进墓葬——保证墓主在那边也有肉吃。",
      "我的绿釉可有讲究:那是低温铅釉,釉里掺了铜,入窑一烧,就烧出浑身的翠绿。有的同伴还和「猪圈」一起随葬,连住处都安排好了。",
      "我在汉代的墓葬里睡了两千年,后来被请进沧州博物馆,成了人见人爱的「小猪」。你看我的獠牙——说不定,我生前还是头野性十足的小野猪呢。",
    ],
    knowledge: [
      { keys: ["绿釉", "釉", "颜色", "为什么绿", "什么釉"], a: "「绿釉」是一种低温铅釉,釉里加入铜就能烧出绿色。它光泽莹润,汉代常用来装饰随葬的陶器。" },
      { keys: ["用途", "干什么", "为什么", "随葬", "明器"], a: "我是「明器」——专门为随葬制作的陶塑。汉代人相信「事死如生」,用我这样的陶猪为墓主在另一个世界供应肉食与财富。" },
      { keys: ["猪圈", "小伙伴", "同伴", "一起"], a: "汉代人常把陶猪和陶猪圈一起随葬,有的猪圈还和厕所修在一起——连喂猪、积肥的农家生活都一并搬进了墓里。" },
      { keys: ["野猪", "家猪", "獠牙", "样子", "造型"], a: "看我的獠牙和鬃毛,我的原型大概是一头野猪。汉代人把猪养得膘肥体壮,猪是「六畜」之一,象征财富和丰足。" },
      { keys: ["在哪", "哪里", "博物馆", "收藏", "沧州"], a: "我收藏在沧州博物馆,是馆里的特色藏品之一;沿着运河去沧州,就能见到我。" },
      { keys: ["出土", "挖掘", "挖出", "发现", "考古", "考古发现", "来历"], a: "像这样的绿釉陶猪,在汉代中小型墓葬中常有出土,西汉晚期尤其流行;我在墓里睡了约两千年,如今被请进沧州博物馆,与运河边的观众见面。" }
    ],
    quiz: [
      { q: "这类绿釉陶猪最常出土于什么墓葬?", options: ["汉代中小型墓葬", "唐代佛塔地宫", "商代甲骨窖穴", "元代驿站"], answer: 0, tip: "西汉晚期至东汉,这类陶猪颇为流行。" },
      { q: "汉代随葬的陶猪,尺寸大多?", options: ["十几厘米上下", "1 米以上", "3 米", "2 毫米"], answer: 0, tip: "明器按真物缩小制作,憨态可掬。" },
      { q: "绿釉陶猪身上的「绿釉」,主要靠釉里的哪种金属呈色?", options: ["铜", "铁", "银", "铝"], answer: 0, tip: "铅釉中加入铜,烧成后呈现绿色。" },
      { q: "汉代人用陶猪随葬,主要是为了?", options: ["给墓主在另一个世界供应肉食", "压住墓室", "当灯照明", "装酒"], answer: 0, tip: "「事死如生」,陶家畜是给墓主的供养。" },
      { q: "汉代随葬品中,常和陶猪配套出现的是?", options: ["陶猪圈", "青铜鼎", "玉龙", "编钟"], answer: 0, tip: "陶猪圈常与陶猪一起入葬,有的还连着厕所。" },
      { q: "陶猪这类专门为随葬制作的器物,叫作?", options: ["明器", "礼器", "兵器", "货币"], answer: 0, tip: "明器即随葬的模型器物。" },
      { q: "这件绿釉陶猪收藏在哪座城市的博物馆?", options: ["沧州", "承德", "保定", "邯郸"], answer: 0, tip: "它是沧州博物馆的特色藏品之一。" }
    ],
    history: "绿釉陶猪是汉代随葬陶塑,属于「明器」。器物作猪形,圆体短足、吻部突出,有的保留獠牙与鬃毛,形态憨健;器表施低温铅绿釉,釉色翠润。汉代社会「事死如生」,常以陶制的猪、狗、鸡、猪圈等家畜和养殖模型随葬,为墓主在另一个世界供应肉食与财富,也折射出汉代家畜饲养与农业生活的面貌;这类陶猪在汉代中小型墓葬中常有出土,西汉晚期至东汉颇为流行。这件绿釉陶猪收藏于沧州博物馆,是该馆的特色藏品之一,其来历与汉代河北地区的厚葬习俗和农耕生活紧密相连。"
  },

