    history: "错金银虎噬鹿屏风座是战国时期中山王墓出土的青铜屏风底座,铸成猛虎噬鹿之形:虎口咬住鹿身、前爪蹬地,小鹿回首挣扎,动势紧张而写实,通体以错金银装饰虎斑鹿纹,是战国青铜雕塑的代表作。中山王墓的屏风原由两件兽形铜座托举。1977 年,它出土于河北平山县三汲乡的中山王墓,现藏于石家庄的河北博物院。"
