      { keys: ["造型", "像什么", "动物", "样子"], a: "我似马非马、似羊非羊、似鹿非鹿,头顶双角、背驮器盖,盖上立凤鸟,器身攀附着龙、虎等好几只小动物——一身都是神兽。" },
      { keys: ["铭文", "字", "邓仲", "谁铸", "主人"], a: "我盖内和器身内壁铸有六字铭文「邓仲作宝尊彝」——邓国的贵族「邓仲」铸造了这件宝器。铭文是解开我身世的钥匙。" },
      { keys: ["做什么用", "用途", "酒", "祭祀", "礼器"], a: "我是盛酒的重器,用于祭祀与宴飨;贵族用我献酒行礼,器物的规格也就是身份与秩序的象征。" },
      { keys: ["多大", "多高", "多长", "尺寸", "厘米"], a: "我通高 38.8 厘米、通长 41.4 厘米,在牺尊里算是体量敦实的一件。" },
      { keys: ["出土", "挖掘", "发现", "考古", "考古发现", "来历", "张家坡"], a: "1984 年,我出土于陕西长安张家坡的井叔家族墓地 M163,现藏中国考古博物馆,是该馆的镇馆之宝之一。" },
      { keys: ["盗墓", "躲过", "幸运"], a: "我的墓室多次被盗扰,身边的不少器物散失了,我却幸运地留存了下来——考古队员见到我时,我的保存状况相当完整。" }
