    history: "错银铜双翼神兽出土于河北平山县战国中山王墓,是河北博物院最负盛名的镇馆之宝之一。它四足据地、双翼上扬,似狮似鸟;错银工艺在铜身铺出细密卷云纹,两千三百年后依然流光隐现。它被视为战国中山国的神秘守护者,如今也是「文物精灵」的品牌图腾——顶栏上那枚徽章,就是它。"
